<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {api,errorText} from '../api/client'
import {items} from '../api'
const props=defineProps<{suggestedName?:string}>()
const form=ref({name:'',mobile:'',gender:'',city:'',education:'',intended_project_id:'',study_purpose:''}),confirmed=ref(false),busy=ref(false),error=ref(''),receipt=ref<any>(null),projects=ref<any[]>([]),pending=ref<any>(null)
onMounted(async()=>{try{projects.value=items(await api.get('/public/projects',{page:1,page_size:100}));const match=projects.value.find(p=>p.name===props.suggestedName);if(match)form.value.intended_project_id=match.id}catch(e){error.value=errorText(e)}})
watch(form,()=>{pending.value=null;receipt.value=null},{deep:true})
async function submit(){if(!confirmed.value||busy.value)return;busy.value=true;error.value='';try{if(!pending.value)pending.value={name:form.value.name,mobile:form.value.mobile,gender:form.value.gender,city:form.value.city,education:form.value.education,intended_project_id:form.value.intended_project_id||null,study_purpose:form.value.study_purpose||null,channel:'FORM',confirmed:true,request_key:crypto.randomUUID()};receipt.value=await api.post('/public/leads',pending.value)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><div class="public-inquiry"><template v-if="receipt"><div class="success-callout">咨询意向已受理</div><p>感谢您的信任，相关服务团队将按登记信息跟进。</p><p class="muted">回执：{{receipt.receiptNo}}</p></template><form v-else @submit.prevent="submit"><label>称呼<input v-model="form.name" autocomplete="name" maxlength="80" required></label><label>联系电话<input v-model="form.mobile" type="tel" autocomplete="tel" required></label><label>性别<select v-model="form.gender" required><option value="">请选择</option><option>男</option><option>女</option><option>不愿透露</option></select></label><label>所在城市<input v-model="form.city" autocomplete="address-level2" maxlength="100" required></label><label>当前学历<select v-model="form.education" required><option value="">请选择</option><option v-for="v in ['初中','高中','中职','大专','本科','硕士及以上','其他']" :key="v">{{v}}</option></select></label><label>意向项目（选填）<select v-model="form.intended_project_id"><option value="">希望获得课程建议</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>学习目标（选填）<textarea v-model="form.study_purpose" rows="2" maxlength="30" placeholder="例如：本科衔接、职业培训"></textarea></label><label class="check-label"><input v-model="confirmed" type="checkbox" required>我已核对以上资料，同意用于本次咨询与联系。</label><button class="btn primary full" :disabled="busy||!confirmed">{{busy?'正在登记…':'确认登记咨询意向'}}</button><p class="visitor-small">提交前请核对联系方式；登记咨询不涉及付款。</p></form><p v-if="error" class="error-text" role="alert">{{error}}</p></div></template>
